import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import { ComposedModal, ModalHeader, ModalBody, ModalFooter, TextInput, Button } from 'carbon-components-react';

function ModalExample() {
  const [open, setOpen] = useState(false);

  return (
    <>
      {typeof document === 'undefined'
        ? null
        : ReactDOM.createPortal(
            <ComposedModal open={open} onClose={() => setOpen(false)}>
              <ModalHeader label="Label" title="Modal heading" />
              <ModalBody hasForm>
                <TextInput
                  id="domain-name"
                  labelText="Domain name"
                  placeholder="e.g. github.com"
                  style={{ width: '100%' }} // Ensure full width
                />
              </ModalBody>
              <ModalFooter>
                <Button kind="secondary" onClick={() => setOpen(false)}>
                  Secondary button
                </Button>
                <Button kind="primary" onClick={() => setOpen(false)}>
                  Primary button
                </Button>
              </ModalFooter>
            </ComposedModal>,
            document.body
          )}
      <Button kind="primary" onClick={() => setOpen(true)}>
        Open modal
      </Button>
    </>
  );
}

export default ModalExample;
